import { Scene, Circle, Create, FadeOut, CameraModel, hex } from "retiam";

export default class MyScene extends Scene {
  async run() {
    this.clearColor(hex("#090E1B"));
    this.camera.model = CameraModel.ORTHOGRAPHIC;
    this.camera.orthoScale = 12;
    this.camera.position.set([0, 0, 20]);
    this.camera.lookAt([0, 0, 0]);

    const circle = new Circle(1, { fill: hex("#38BDF8") });
    circle.move([-2, 0, 0]);
    this.add(circle);
    await this.play(new Create(circle, { duration: 1200 }));
    await this.play(circle.animate.move([2, 0, 0]), { duration: 1000 });
    await this.wait(800);
    await this.play(new FadeOut(circle, { duration: 600 }));
    await this.wait(400);
  }
}

import { defineConfig } from 'vite';

export default defineConfig({
  // Retiam already ships as split ESM with assets relative to its modules.
  optimizeDeps: { exclude: ['retiam'] }
});

import { Scene } from "retiam";

async function bootstrap() {
  const canvas = document.querySelector<HTMLCanvasElement>("#canvas");
  if (!canvas) throw new Error("Missing scene canvas.");
  if (!navigator.gpu) throw new Error("WebGPU is unavailable in this browser context.");

  // The CLI supplies ?file=scenes/MyScene.ts; normal preview uses this default.
  const file = new URLSearchParams(location.search).get("file") || "scenes/MyScene.ts";
  const sceneModule = await import(/* @vite-ignore */ "/" + file.replace(/^\/+/, ""));
  const SceneClass = sceneModule.default;
  if (typeof SceneClass !== "function" || !(SceneClass.prototype instanceof Scene)) {
    throw new Error("The scene module must default-export a Scene subclass.");
  }

  const scene: Scene = new SceneClass();
  await scene.start(canvas);
  window.addEventListener("pagehide", () => scene.destroy(), { once: true });
}

bootstrap().catch(console.error);

